-- Candidate-only frame ownership observation/control ports.
fr_enable : in std_logic := '0';
fr_expected_height : in std_logic_vector(12 downto 0) := std_logic_vector(to_unsigned(720,13));
fr_base : in std_logic_vector(31 downto 0) := (others => '0');
fr_frame_start : out std_logic;
fr_command_generate : out std_logic;
fr_last_command : out std_logic;
fr_geometry_good : out std_logic;
fr_abort : out std_logic;

fr_frame_start <= load_new_addr;
fr_command_generate <= write_cmnd_cmb;
fr_last_command <= '1' when write_cmnd_cmb='1' and unsigned(vert_count)=1 else '0';
fr_geometry_good <= '1' when unsigned(crnt_hsize)=3840 and unsigned(crnt_vsize)=unsigned(fr_expected_height) and unsigned(crnt_stride)=3840 else '0';
fr_abort <= stop or halt;

